// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public {
        c = new PoCGame(address(this), 1 ether);
    }

    function testFuzz_property(address caller, uint256 amount) public {
        amount = 1 ether;
        vm.assume(caller != address(this));
        vm.assume(caller > address(9));

        vm.startPrank(address(this));
        c.OpenToThePublic();
        vm.stopPrank();

        Proxy proxy = new Proxy();

        vm.deal(address(proxy), amount);

        bool success;
        uint256 wagerBefore = c.hasPlayerWagered(address(proxy)) ? 1 : 0;
        vm.prank(address(proxy));
        try proxy.callWager(address(c), amount) {
            success = true;
        } catch {
            success = false;
        }
        uint256 wagerAfter = c.hasPlayerWagered(address(proxy)) ? 1 : 0;

        assertTrue(!success, "Invariant broken: contract caller succeeded in wager");
    }
}

contract Proxy {
    function callWager(address target, uint256 amount) external payable {
        (bool _s,) = target.call{value: amount}(abi.encodeWithSignature("wager()"));
        require(_s, "wager failed");
    }
}
